import {sources,passages,topics,corpusVersion} from './corpus.js';
export const normalize=s=>s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[-‐]/g,' ').replace(/\s+/g,' ').trim();
export function candidates(text){return text.split(/(?<=[.!?])\s+|\n+/).map(s=>s.trim()).filter(Boolean).slice(0,3);}
export function suggestKind(text){const s=normalize(text);if(/\b(prefiro|melhor|bonit[oa]|deveria|vale a pena)\b/.test(s))return 'opinion';if(/\b(sera|serao|vai|irao|preve|previsao)\b/.test(s))return 'prediction';if(/^(a tecnologia faz mal|isso e verdade|isso faz mal|e confiavel)[?.!]*$/.test(s))return 'context';return 'fact';}
export function search(text){const s=normalize(text);const ranked=topics.map(t=>({t,score:t.terms.reduce((n,term)=>n+(s.includes(term)?term.length:0),0)})).filter(x=>x.score>0).sort((a,b)=>b.score-a.score);if(!ranked.length)return {corpusVersion,topic:'',summary:'Não encontrei evidências sobre essa frase neste acervo. Isso não mostra que ela é falsa ou verdadeira.',gap:'O assunto pode estar fora da cobertura, ou a frase pode precisar de contexto.',question:'Que evidência você precisaria encontrar para decidir?',evidence:[]};const t=ranked[0].t;return {corpusVersion,topic:t.id,summary:t.summary,gap:t.gap,question:t.question,evidence:t.entries.slice(0,3).map(id=>{const p=passages.find(x=>x.id===id),src=sources.find(x=>x.id===p.sourceId);return {...p,source:{...src}};})};}
